  function home(){const el=document.getElementById('homeScreen');if(!el)return;el.innerHTML=`<div class="v25Hero"><div class="v25Mark"><i></i><i></i><i></i><i></i></div><div class="v25Brand">V-BRAIN</div></div><div class="v25Home"><div class="v25Core"><button id="vbrainScoreV8" type="button"><div class="v25ScoreTop"><div><div class="v25Kicker">Behaviour intelligence</div><div class="v25ScoreTitle">Your signal today</div><div class="v25ScoreCopy" id="v25ScoreCopy">You have started moving. V-Brain is watching for follow-through, not taps.</div></div><div class="v25Orb" id="v25Orb"><strong id="v25Score">0</strong><span>V SCORE</span></div></div><div class="v25Mini"><div><b id="v25TaskToday">0</b><small>Tasks</small></div><div><b id="v25LearnToday">0</b><small>Learn</small></div><div><b id="v25MoveWeek">0</b><small>Move</small></div></div><div class="v25BrainLink"><span id="v25BrainMeta">8 live traits · 6 connections</span><span>›</span></div></button><button class="v25HomeCard gym" data-route="gym" type="button"><div class="v25CardHead"><span class="v25CardLabel">Gym</span><span class="v25CardMeta" id="v25GymMeta">0 this week ›</span></div><div class="v25CardBody"><div class="v25Icon">↑</div><div class="v25Copy"><h2>Train</h2><p id="v25GymPlanText">Full body · 45 min</p></div></div></button><button class="v25HomeCard tube" data-route="tube" type="button"><div class="v25CardHead"><span class="v25CardLabel">Learn</span><span class="v25CardMeta">Cards ›</span></div><div class="v25LearnRow"><div class="v25Copy"><h2>Tube Learning</h2><p id="v25TubeText">0 completed so far</p></div><div class="v25LearnRing" id="v25LearnRing"><strong id="v25LearnCount">0</strong><small>LEARNED</small></div></div></button><button class="v25HomeCard todos" data-route="todos" type="button"><div class="v25CardHead"><span class="v25CardLabel">Tasks</span><span class="v25CardMeta" id="v25TodoMeta">0 open ›</span></div><div class="v25CardBody"><div class="v25Icon" style="font-size:0"><span style="width:38px;height:38px;border-radius:50%;border:2px solid rgba(255,255,255,.55)"></span></div><div class="v25Copy"><h2>To-Dos</h2><p id="v25TodoText">Everything is done</p></div></div></button><button class="v25HomeCard calendar" data-route="calendar" type="button"><div class="v25CardHead"><span class="v25CardLabel">Today</span><span class="v25CardMeta">View day ›</span></div><div class="v25CardBody"><div class="v25Icon">◷</div><div class="v25Copy"><h2>Calendar</h2><p>Your events, time and place.</p></div></div></button><div id="v25DynamicHome"></div></div></div>`;el.querySelector('#vbrainScoreV8').onclick=openBrain;el.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>show(b.dataset.route))}

  const GYM_KEY='homeGymStateV1';
  const gymPlans={
    full:{name:'Full body',short:'Strength',minutes:45,accent:'Strength · 45 min',items:[['Squat / leg press','3 × 8–10'],['Bench press / push-ups','3 × 8–12'],['Row / lat pulldown','3 × 8–12'],['Romanian deadlift','3 × 8–10'],['Plank / carry','3 rounds']]},
    quick:{name:'Quick session',short:'Quick',minutes:20,accent:'Efficient · 20 min',items:[['Leg press / squat','3 × 10'],['Chest press / push-ups','3 × 10'],['Row / pulldown','3 × 10'],['Core finisher','3 rounds']]},
    recovery:{name:'Recovery',short:'Recovery',minutes:15,accent:'Easy · 15 min',items:[['Incline walk / bike','8 min easy'],['Hip + ankle mobility','3 min'],['Shoulder mobility','2 min'],['Breathing cooldown','2 min']]}
  };
  let gymTimer=0;
  function loadGymState(){const raw=readState(GYM_KEY,{});return{selected:gymPlans[raw.selected]?raw.selected:'full',active:raw.active&&gymPlans[raw.active.plan]?raw.active:null,history:Array.isArray(raw.history)?raw.history:[]}}
  function saveGymState(state){persistState(GYM_KEY,state);updateHome()}
  function gymWeek(state=loadGymState()){return state.history.filter(x=>Number(x.endedAt)>=now()-7*86400000).length}
  function gymClock(started){const t=Math.max(0,Math.floor((now()-Number(started||now()))/1000));return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`}
  function ensureGym(){let g=document.getElementById('gymScreen');if(g)return g;g=document.createElement('section');g.className='screen';g.id='gymScreen';g.innerHTML=`<div class="v25GymHead"><button class="v25GymBack" type="button" aria-label="Back">‹</button><div><small>GYM</small><h1>Train well.</h1></div><div class="v25GymWeek" id="v25GymWeek"></div></div><div class="v25GymBody"><div class="v25Slot" id="v25SlotGym"></div><div class="v25GymHero"><p>Simple enough to start. Structured enough to improve.</p></div><div class="v25GymTabs" id="v25GymTabs"></div><div class="v25GymSession" id="v25GymSession"></div><div class="v25GymRecent" id="v25GymRecent"></div></div>`;document.querySelector('.app')?.appendChild(g);g.querySelector('.v25GymBack').onclick=()=>show('home');return g}
  function renderGym(){const g=ensureGym(),s=loadGymState(),id=s.active?.plan||s.selected,plan=gymPlans[id],tabs=g.querySelector('#v25GymTabs'),box=g.querySelector('#v25GymSession');g.querySelector('#v25GymWeek').textContent=`${gymWeek(s)} this week`;
    tabs.innerHTML=Object.entries(gymPlans).map(([key,p])=>`<button type="button" data-plan="${key}" class="${key===id?'selected':''}" ${s.active?'disabled':''}><b>${p.short}</b><small>${p.minutes} min</small></button>`).join('');tabs.querySelectorAll('button').forEach(btn=>btn.onclick=()=>{const state=loadGymState();state.selected=btn.dataset.plan;saveGymState(state);renderGym();log('gym_plan_select',{plan:state.selected})});
    const done=new Set(s.active?.completed||[]);box.innerHTML=`<div class="v25GymSessionHead"><div><small>${s.active?'SESSION LIVE':'TODAY'}</small><h2>${plan.name}</h2><p>${plan.accent}</p></div><div class="v25GymClock" id="v25GymClock">${s.active?gymClock(s.active.startedAt):plan.minutes+'m'}</div></div><div class="v25GymSteps">${plan.items.map(([name,reps],i)=>`<button class="v25GymStep ${done.has(i)?'done':''}" data-step="${i}" ${s.active?'':'disabled'} type="button"><span class="v25GymNum">${done.has(i)?'✓':i+1}</span><span><b>${name}</b><small>${reps}</small></span></button>`).join('')}</div><button class="v25GymDone" type="button" id="v25GymDone">${s.active?'Finish session':'Start workout'}</button>`;
    box.querySelectorAll('[data-step]').forEach(btn=>btn.onclick=()=>{const state=loadGymState();if(!state.active)return;const i=Number(btn.dataset.step),completed=new Set(state.active.completed||[]);completed.has(i)?completed.delete(i):completed.add(i);state.active.completed=[...completed];saveGymState(state);log('gym_exercise_toggle',{plan:state.active.plan,index:i,done:completed.has(i)});renderGym()});
    box.querySelector('#v25GymDone').onclick=()=>{const state=loadGymState();if(!state.active){state.active={plan:state.selected,startedAt:now(),completed:[]};saveGymState(state);log('gym_start',{plan:state.selected})}else{const finished={plan:state.active.plan,startedAt:state.active.startedAt,endedAt:now(),completed:(state.active.completed||[]).length,total:gymPlans[state.active.plan].items.length};state.history.push(finished);state.history=state.history.slice(-40);state.active=null;saveGymState(state);log('gym_complete',finished)}renderGym()};
    clearTimeout(gymTimer);if(s.active&&g.classList.contains('show'))gymTimer=setTimeout(function tickGymClock(){const clock=g.querySelector('#v25GymClock'),state=loadGymState();if(!g.classList.contains('show')||!state.active){gymTimer=0;return}if(clock)clock.textContent=gymClock(state.active.startedAt);gymTimer=setTimeout(tickGymClock,1000)},1000);
    const last=s.history.at(-1);g.querySelector('#v25GymRecent').textContent=last?`Last session · ${gymPlans[last.plan]?.name||'Workout'} · ${last.completed}/${last.total} exercises`:'Complete one session to start your history.';
  }
  window.openHomeGym=()=>show('gym');

  let enteredScreenAt=now(),scrollMilestone=0;
  function recordDwell(){const ms=now()-enteredScreenAt;if(ms>=1000&&ms<86400000)log('screen_dwell',{name:screen(),ms});enteredScreenAt=now();scrollMilestone=0}
  function show(name){if(name==='gym')ensureGym();if(typeof currentScreen!=='undefined'&&currentScreen==='tube'&&name!=='tube'&&document.getElementById('reader')?.classList.contains('show')){try{closeReader()}catch(_){}}const target=document.getElementById(name+'Screen');if(!target)return;recordDwell();document.querySelectorAll('.screen').forEach(x=>x.classList.remove('show'));target.classList.add('show');try{currentScreen=name}catch(_){}window.scrollTo(0,0);if(name==='todos'){renderTodosLean();setTimeout(()=>refreshTasks(),0)}if(name==='calendar'){try{renderCalendar()}catch(_){}log('calendar_open',{})}if(name==='tube'){installTubeContent();try{renderDeck()}catch(_){}forceTube()}if(name==='gym'){renderGym();log('gym_open',{})}renderSlot(name);updateHome();log('screen_enter',{name})}

  // Keep the daily list small while retaining older HOME Sync imports for selective recovery.
  const TASK_MIGRATION='vbrainTodoMigrationV27',TASK_HIDDEN='vbrainHiddenTaskIdsV27',TASK_OLDER='vbrainOlderTasksV27',TASK_BACKUP='vbrainTodoBackupV27',TASK_SCREENED='vbrainBacklogScreenedV27';
  let hiddenTaskIds=new Set(readState(TASK_HIDDEN,[])),olderTasks=readState(TASK_OLDER,[]);
  if(!Array.isArray(olderTasks))olderTasks=[];for(const t of olderTasks)if(t?.id)hiddenTaskIds.add(String(t.id));
