  function showNode(n){if(!detail||!n)return;const linked=allModel.edges.filter(e=>e.a===n.id||e.b===n.id).map(e=>allModel.nodes.find(x=>x.id===(e.a===n.id?e.b:e.a))?.label).filter(Boolean),level=n.active===false?'Historical branch':n.confidence<25?'Early signal':n.confidence<55?'Developing pattern':'Established signal';detail.innerHTML=`<small>${esc(level)} · ${Math.round(n.confidence||0)}% confidence · ${Number(n.evidenceCount)||0} signals</small><span class="v25BrainValue">${Math.round(n.value||0)}</span><h2>${esc(n.label||n.id)}</h2><p>${esc(n.description||'This signal changes as V-Brain observes more meaningful behaviour.')}</p><p>${n.active===false?'This branch is quiet now, but remains part of your history.':n.value>=70?'V-Brain currently sees this as one of the stronger patterns in your behaviour.':n.value>=45?'This pattern is becoming visible as more evidence arrives.':'The signal is weak or early; V-Brain does not treat it as a fixed trait.'}</p>${linked.length?`<p><b>Connected with:</b> ${esc(linked.slice(0,12).join(', '))}${linked.length>12?` +${linked.length-12} more`:''}</p>`:''}<div class="v25BrainReasons">${(n.reasons||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div>${allModel.nodes.length>GRAPH_VIEW_LIMIT?'<button class="v25More" id="v25FocusBranch" type="button">Explore this branch</button>':''}`;const focus=detail.querySelector('#v25FocusBranch');if(focus)focus.onclick=()=>{brainFocus=n.id;brainQuery='';brain.querySelector('.v25BrainSearch input').value='';visibleBrain()}}
  function resizeCanvas(){if(!canvas)return;const d=Math.min(2,window.devicePixelRatio||1),w=Math.max(1,Math.round(canvas.clientWidth*d)),h=Math.max(1,Math.round(canvas.clientHeight*d));if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}ctx.setTransform(d,0,0,d,0,0)}
