  document.addEventListener('click',e=>{const submit=e.target?.closest?.('#submit'),draft=submit&&submissions.get(submit);if(!draft)return;submissions.delete(submit);if(!document.getElementById('next')?.classList.contains('show'))return;const list=tubeState?.completed||[],last=list[list.length-1];if(!last||last.id!==draft.card.id)return;const requestId=`review-${last.id}-${last.at}`,attemptId=`attempt-${last.id}-${last.at}`,attempt={id:attemptId,attemptId,requestId,cardId:last.id,at:last.at,title:last.title,topic:draft.card.topic,question:draft.card.q,prompt:draft.prompt,sentence:draft.sentence,selected:draft.selected,correct:draft.card.correct,options:draft.card.options,lead:draft.card.lead,takeaway:draft.card.takeaway,sections:draft.card.sections,method:document.getElementById('reader')?.dataset.learningMethod||'quiz',reviewStatus:'pending'};last.sentence=draft.sentence;last.selected=draft.selected;last.correct=draft.card.correct;last.quizCorrect=draft.selected===draft.card.correct;last.prompt=draft.prompt;last.reviewStatus='pending';saveStore('tubeState',tubeState);const q=load('v25LearningAttempts',[]);q.push(attempt);save('v25LearningAttempts',q.slice(-160));try{AdaptiveNative?.queuePrivateActivity?.(JSON.stringify({...attempt,kind:'learning_attempt',source:'vbrain-one-ui-v25',screen:'tube'}))}catch(_){}reviews.set(requestId,attempt);try{AdaptiveNative?.reviewSentence?.(JSON.stringify(attempt))}catch(_){}log('tube_complete',{cardId:last.id,score:last.total,hasSentence:true});updateHome()});
